function validate(input) {
  const [{ Departments = [], Students = [] }] = input;
  const departments = new Set(), students = new Set();
  for (const [id] of Departments) {
    if (id === null) return 'Every department needs an id.';
    if (departments.has(id)) return `Department id ${id} appears twice.`;
    departments.add(id);
  }
  for (const [id, , department] of Students) {
    if (id === null) return 'Every student needs an id.';
    if (students.has(id)) return `Student id ${id} appears twice.`;
    if (department === null) return `Student ${id} needs a department_id.`;
    students.add(id);
  }
  return null;
}

