function generate(rand, size) {
  const names = ['Alice', 'Bob', 'Jennifer', 'John', 'Jasmine', 'Steve', 'Luis', 'Daiana', 'Madelynn', 'Jonathan'];
  const subjects = ['Electrical Engineering', 'Computer Engineering', 'Business Administration', 'Mathematics', 'Physics', 'History'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const pool = small ? 8 : 800;
  const Departments = [];
  for (let id = 1; id <= pool; id++) if (rand() < 0.5) Departments.push([id, pick(subjects)]);
  const count = small ? Math.floor(rand() * 9) : 2000;
  const ids = [];
  for (let id = 1; ids.length < count; id++) if (rand() < 0.7) ids.push(id);
  // Shuffle the student ids so rows do not come in id order.
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  // Department ids reach a little past the pool, so some students point at departments that never existed.
  const Students = ids.map(id => [id, pick(names), 1 + Math.floor(rand() * (pool + (small ? 3 : 200)))]);
  return [{ Departments, Students }];
}
